@push('ct_quick_js')<script>$(function(){function sync($type){var $form=$type.closest('form'),type=$type.val(),$qty=$form.find('.ct-subcontract-qty input'),$rate=$form.find('.ct-subcontract-rate input'),$boq=$form.find('.ct-subcontract-boq option:selected');$qty.prop('readonly',false);$rate.prop('readonly',false);if(type==='lump_sum'){$qty.val('1').prop('readonly',true)}if(type==='percentage'){$rate.val($boq.data('total')||0).prop('readonly',true)}}$(document).on('change','.ct-subcontract-type,.ct-subcontract-boq',function(){sync($(this).closest('form').find('.ct-subcontract-type'))});$('.ct-subcontract-type').each(function(){sync($(this))})})</script>@endpush
